20	// Adapter implements domain.DbWorkspaceAdapter.
21	type Adapter struct {
22		pool *pgxpool.Pool
23		q    *database.Queries
24	}
25	
26	// New creates a new Adapter from an existing pgxpool.Pool.
27	func New(pool *pgxpool.Pool) *Adapter {
28		return &Adapter{pool: pool, q: database.New(pool)}
29	}
30	
31	// Connect creates a pgxpool.Pool from the given DATABASE_URL and returns a new Adapter.
32	func Connect(ctx context.Context, databaseURL string) (*Adapter, error) {
33		pool, err := pgxpool.New(ctx, databaseURL)
34		if err != nil {
35			return nil, fmt.Errorf("pgxpool.New: %w", err)
36		}
37		if err := pool.Ping(ctx); err != nil {
38			pool.Close()
39			return nil, fmt.Errorf("ping db: %w", err)
40		}
41		return New(pool), nil
42	}
43	
44	// Close releases the connection pool.
45	func (a *Adapter) Close() { a.pool.Close() }
46	
47	// ListWorkspaces returns summary rows for all saved workspaces.
48	func (a *Adapter) ListWorkspaces(ctx context.Context) ([]domain.WorkspaceSummary, error) {
49		rows, err := a.q.ListWorkspaces(ctx)
50		if err != nil {
51			return nil, dbErr("list workspaces", err)
52		}
53	
54		out := make([]domain.WorkspaceSummary, 0, len(rows))
55		for _, r := range rows {
56			latestRun, _ := a.q.GetLatestSyncRun(ctx, r.ID) //nolint:errcheck
57			ss := syncRunToSourceState(&latestRun, nil)
58	
59			out = append(out, domain.WorkspaceSummary{
60				ID:          uuidStr(r.ID),
61				Name:        r.Name,
62				Slug:        r.Slug,
63				RepoURL:     githubRepoURL(ctx, a.q, r.ID),
64				SourceState: ss,
65				UpdatedAt:   r.UpdatedAt.Time,
66			})
67		}
68		return out, nil
69	}
