71	// GetWorkspace returns the full workspace detail.
72	func (a *Adapter) GetWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, error) {
73		uid, err := parseUUID(workspaceID)
74		if err != nil {
75			return nil, err
76		}
77	
78		ws, err := a.q.GetWorkspace(ctx, uid)
79		if err != nil {
80			if errors.Is(err, pgx.ErrNoRows) {
81				return nil, domain.NewDatabaseError(domain.ErrDatabaseNotFound, "workspace not found: "+workspaceID)
82			}
83			return nil, dbErr("get workspace", err)
84		}
85	
86		features, err := a.q.ListWorkspaceFeatures(ctx, uid)
87		if err != nil {
88			return nil, dbErr("list features", err)
89		}
90	
91		tasks, err := a.q.ListWorkspaceTasks(ctx, uid)
92		if err != nil {
93			return nil, dbErr("list tasks", err)
94		}
95	
96		latestRun, _ := a.q.GetLatestSyncRun(ctx, uid) //nolint:errcheck
97		ss := syncRunToSourceState(&latestRun, nil)
98	
99		featureSummaries := make([]domain.FeatureSummary, 0, len(features))
100		for _, f := range features {
101			featureSummaries = append(featureSummaries, rowToFeatureSummary(f, tasks))
102		}
103	
104		taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
105		for _, t := range tasks {
106			taskSummaries = append(taskSummaries, rowToTaskSummary(t))
107		}
108	
109		return &domain.WorkspaceDetail{
110			WorkspaceSummary: domain.WorkspaceSummary{
111				ID:          workspaceID,
112				Name:        ws.Name,
113				Slug:        ws.Slug,
114				RepoURL:     githubRepoURL(ctx, a.q, uid),
115				SourceState: ss,
116				UpdatedAt:   ws.UpdatedAt.Time,
117			},
118			Features: featureSummaries,
119			Tasks:    taskSummaries,
120		}, nil
121	}
