123	// GetFeature returns the full feature detail.
124	func (a *Adapter) GetFeature(ctx context.Context, workspaceID, featureID string) (*domain.FeatureDetail, error) {
125		uid, err := parseUUID(workspaceID)
126		if err != nil {
127			return nil, err
128		}
129	
130		f, err := a.q.GetWorkspaceFeature(ctx, database.GetWorkspaceFeatureParams{
131			WorkspaceID: uid,
132			FeatureID:   featureID,
133		})
134		if err != nil {
135			if errors.Is(err, pgx.ErrNoRows) {
136				return nil, domain.NewDatabaseError(domain.ErrDatabaseNotFound, "feature not found: "+featureID)
137			}
138			return nil, dbErr("get feature", err)
139		}
140	
141		docs, err := a.q.ListFeatureDocuments(ctx, database.ListFeatureDocumentsParams{
142			WorkspaceID: uid,
143			FeatureID:   featureID,
144		})
145		if err != nil {
146			return nil, dbErr("list feature documents", err)
147		}
148	
149		tasks, err := a.q.ListFeatureTasks(ctx, database.ListFeatureTasksParams{
150			WorkspaceID: uid,
151			FeatureID:   featureID,
152		})
153		if err != nil {
154			return nil, dbErr("list feature tasks", err)
155		}
156	
157		actEvents, err := a.q.ListFeatureActivityEvents(ctx, database.ListFeatureActivityEventsParams{
158			WorkspaceID: uid,
159			FeatureID:   featureID,
160		})
161		if err != nil {
162			return nil, dbErr("list feature activity", err)
163		}
164	
165		latestRun, _ := a.q.GetLatestSyncRun(ctx, uid) //nolint:errcheck
166		ss := syncRunToSourceState(&latestRun, nil)
167	
168		allTasks, _ := a.q.ListWorkspaceTasks(ctx, uid) //nolint:errcheck
169		summary := rowToFeatureSummary(f, allTasks)
170	
171		docLinks := make([]domain.DocumentLink, 0, len(docs))
172		for _, d := range docs {
173			dl := domain.DocumentLink{
174				DocumentType: d.DocumentType,
175				SourcePath:   d.SourcePath,
176			}
177			if d.URL != nil {
178				dl.URL = *d.URL
179			}
180			docLinks = append(docLinks, dl)
181		}
182	
183		taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
184		for _, t := range tasks {
185			taskSummaries = append(taskSummaries, rowToTaskSummary(t))
186		}
187	
188		activity := make([]domain.ActivityEvent, 0, len(actEvents))
189		for _, e := range actEvents {
190			activity = append(activity, rowToActivityEvent(e))
191		}
192	
193		return &domain.FeatureDetail{
194			FeatureSummary: summary,
195			WorkspaceID:    workspaceID,
196			Documents:      docLinks,
197			Tasks:          taskSummaries,
198			Activity:       activity,
199			SourceState:    ss,
200		}, nil
201	}
