203	// GetTask returns the full task detail.
204	func (a *Adapter) GetTask(ctx context.Context, workspaceID, taskID string) (*domain.TaskDetail, error) {
205		uid, err := parseUUID(workspaceID)
206		if err != nil {
207			return nil, err
