215			if errors.Is(err, pgx.ErrNoRows) {
216				return nil, domain.NewDatabaseError(domain.ErrDatabaseNotFound, "task not found: "+taskID)
217			}
218			return nil, dbErr("get task", err)
219		}
220	
221		var featureID string
222		if t.FeatureID != "" {
223			featureID = t.FeatureID
224		}
225	
226		actEvents, _ := a.q.ListTaskActivityEvents(ctx, database.ListTaskActivityEventsParams{ //nolint:errcheck
227			WorkspaceID: uid,
228			FeatureID:   featureID,
229			TaskID:      taskID,
230		})
231	
232		activity := make([]domain.ActivityEvent, 0, len(actEvents))
