237		return &domain.TaskDetail{
238			TaskSummary: rowToTaskSummary(t),
239			WorkspaceID: workspaceID,
240			DependsOn:   unmarshalStringSlice(t.DependsOn),
241			Execution:   unmarshalExecution(t.Execution),
242			Activity:    activity,
243		}, nil
244	}
