305	// SaveSnapshot upserts all core tables from the given snapshot inside a single transaction.
306	func (a *Adapter) SaveSnapshot(ctx context.Context, workspaceID string, snapshot *domain.WorkspaceSnapshot) error {
307		uid, err := parseUUID(workspaceID)
308		if err != nil {
309			return err
310		}
311	
312		tx, err := a.pool.BeginTx(ctx, pgx.TxOptions{})
313		if err != nil {
314			return fmt.Errorf("begin transaction: %w", err)
315		}
316		defer tx.Rollback(ctx) //nolint:errcheck
317	
318		if err := upsertSnapshot(ctx, a.q.WithTx(tx), uid, snapshot); err != nil {
319			return err
320		}
321		return tx.Commit(ctx)
322	}
