324	// GetActiveSnapshot returns the latest WorkspaceSnapshot reconstructed from core tables.
325	func (a *Adapter) GetActiveSnapshot(ctx context.Context, workspaceID string) (*domain.WorkspaceSnapshot, error) {
326		uid, err := parseUUID(workspaceID)
327		if err != nil {
328			return nil, err
329		}
330	
331		ws, err := a.q.GetWorkspace(ctx, uid)
332		if err != nil {
333			if errors.Is(err, pgx.ErrNoRows) {
334				return nil, nil
335			}
336			return nil, dbErr("get workspace", err)
337		}
338	
339		features, err := a.q.ListWorkspaceFeatures(ctx, uid)
340		if err != nil {
341			return nil, dbErr("list features for snapshot", err)
342		}
343	
344		repos, err := a.q.ListWorkspaceRepos(ctx, uid)
345		if err != nil {
346			return nil, dbErr("list repos for snapshot", err)
347		}
348	
349		src, _ := a.q.GetGitHubSource(ctx, uid) //nolint:errcheck
350	
351		featureSnapshots := make([]domain.FeatureSnapshot, 0, len(features))
352		for _, f := range features {
353			fs, err := buildFeatureSnapshot(ctx, a.q, uid, f)
354			if err != nil {
355				return nil, err
356			}
357			featureSnapshots = append(featureSnapshots, fs)
358		}
359	
360		repoEntries := make([]domain.RepoEntry, 0, len(repos))
361		for _, r := range repos {
362			re := domain.RepoEntry{RepoID: r.RepoID}
363			if r.BaseBranch != nil {
364				re.BaseBranch = *r.BaseBranch
365			}
366			repoEntries = append(repoEntries, re)
367		}
368	
369		repoURL := ""
370		if src.RepoURL != "" {
371			repoURL = src.RepoURL
372		}
373	
374		return &domain.WorkspaceSnapshot{
375			WorkspaceID: workspaceID,
376			Name:        ws.Name,
377			Slug:        ws.Slug,
378			RepoURL:     repoURL,
379			Features:    featureSnapshots,
380			Repos:       repoEntries,
381		}, nil
382	}
