401	// upsertSnapshot is the transactional core of SaveSnapshot.
402	func upsertSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, snap *domain.WorkspaceSnapshot) error {
403		// Upsert workspace record (slug is the natural key).
404		_, err := q.UpsertWorkspace(ctx, database.UpsertWorkspaceParams{
405			ID:               uid,
406			Slug:             snap.Slug,
407			Name:             snap.Name,
408			ManagementRepoID: "management-repo",
409		})
410		if err != nil {
411			return fmt.Errorf("upsert workspace: %w", err)
412		}
413	
414		// Upsert repos.
415		repoIDs := make([]string, 0, len(snap.Repos))
416		for _, r := range snap.Repos {
417			bp := ptrStr(r.BaseBranch)
418			_, err := q.UpsertWorkspaceRepo(ctx, database.UpsertWorkspaceRepoParams{
419				WorkspaceID: uid,
420				RepoID:      r.RepoID,
421				BaseBranch:  bp,
422			})
423			if err != nil {
424				return fmt.Errorf("upsert repo %s: %w", r.RepoID, err)
425			}
426			repoIDs = append(repoIDs, r.RepoID)
427		}
428		if err := q.DeleteWorkspaceReposNotIn(ctx, database.DeleteWorkspaceReposNotInParams{
429			WorkspaceID: uid,
430			RepoIds:     repoIDs,
431		}); err != nil {
432			return fmt.Errorf("delete stale repos: %w", err)
433		}
434	
435		// Upsert features, docs, tasks, activity.
436		featureIDs := make([]string, 0, len(snap.Features))
437		for _, f := range snap.Features {
438			if err := upsertFeatureSnapshot(ctx, q, uid, f); err != nil {
439				return err
440			}
441			featureIDs = append(featureIDs, f.FeatureID)
442		}
443		if err := q.DeleteWorkspaceFeaturesNotIn(ctx, database.DeleteWorkspaceFeaturesNotInParams{
444			WorkspaceID: uid,
445			FeatureIds:  featureIDs,
446		}); err != nil {
447			return fmt.Errorf("delete stale features: %w", err)
448		}
449	
450		return nil
451	}
