453	func upsertFeatureSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, f domain.FeatureSnapshot) error {
454		stages, _ := json.Marshal(nil) //nolint:errcheck
455		_, err := q.UpsertWorkspaceFeature(ctx, database.UpsertWorkspaceFeatureParams{
456			WorkspaceID:   uid,
457			FeatureID:     f.FeatureID,
458			Title:         f.Title,
459			FeatureStatus: ptrStr(f.Status),
460			CurrentStage:  ptrStr(f.CurrentStage),
461			NextAction:    ptrStr(f.NextAction),
462			Stages:        stages,
463			SourcePath:    f.SourcePath,
464			SourceHash:    ptrStr(f.SourceHash),
465		})
466		if err != nil {
467			return fmt.Errorf("upsert feature %s: %w", f.FeatureID, err)
468		}
469	
470		// Upsert documents.
471		docTypes := make([]string, 0, len(f.Documents))
472		for _, d := range f.Documents {
473			_, err := q.UpsertFeatureDocument(ctx, database.UpsertFeatureDocumentParams{
474				WorkspaceID:  uid,
475				FeatureID:    f.FeatureID,
476				DocumentType: d.DocumentType,
477				SourcePath:   d.SourcePath,
478				URL:          ptrStr(d.URL),
479			})
480			if err != nil {
481				return fmt.Errorf("upsert document %s/%s: %w", f.FeatureID, d.DocumentType, err)
482			}
483			docTypes = append(docTypes, d.DocumentType)
484		}
485		if err := q.DeleteFeatureDocumentsNotIn(ctx, database.DeleteFeatureDocumentsNotInParams{
486			WorkspaceID:   uid,
487			FeatureID:     f.FeatureID,
488			DocumentTypes: docTypes,
489		}); err != nil {
490			return fmt.Errorf("delete stale documents for %s: %w", f.FeatureID, err)
491		}
492	
493		// Upsert tasks.
494		taskIDs := make([]string, 0, len(f.Tasks))
495		for _, t := range f.Tasks {
496			if err := upsertTaskSnapshot(ctx, q, uid, f.FeatureID, t); err != nil {
497				return err
498			}
499			taskIDs = append(taskIDs, t.TaskID)
500		}
501		if err := q.DeleteFeatureTasksNotIn(ctx, database.DeleteFeatureTasksNotInParams{
502			WorkspaceID: uid,
503			FeatureID:   f.FeatureID,
504			TaskIds:     taskIDs,
505		}); err != nil {
506			return fmt.Errorf("delete stale tasks for %s: %w", f.FeatureID, err)
507		}
508	
509		// Upsert feature-level activity (task_id = nil).
510		if err := upsertFeatureActivity(ctx, q, uid, f); err != nil {
511			return err
512		}
513	
514		return nil
515	}
