517	func upsertTaskSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, featureID string, t domain.TaskSnapshot) error {
518		dependsOn, _ := json.Marshal(t.DependsOn)     //nolint:errcheck
519		execution, _ := json.Marshal(t.Execution)     //nolint:errcheck
520		pr, _ := json.Marshal(t.PR)                   //nolint:errcheck
521		wsPr, _ := json.Marshal(t.WorkspacePR)        //nolint:errcheck
522	
523		_, err := q.UpsertWorkspaceTask(ctx, database.UpsertWorkspaceTaskParams{
524			WorkspaceID:   uid,
525			FeatureID:     featureID,
526			TaskID:        t.TaskID,
527			Title:         t.Title,
528			Repo:          ptrStr(t.Repo),
529			Status:        ptrStr(t.Status),
530			DependsOn:     dependsOn,
531			BlockedReason: ptrStr(t.BlockedReason),
532			Branch:        ptrStr(t.Branch),
533			Execution:     execution,
534			Pr:            pr,
535			WorkspacePr:   wsPr,
536			SourcePath:    t.SourcePath,
537			SourceHash:    ptrStr(t.SourceHash),
538		})
539		if err != nil {
540			return fmt.Errorf("upsert task %s/%s: %w", featureID, t.TaskID, err)
541		}
542	
543		// Upsert task-level activity from the task log.
544		if err := upsertTaskActivity(ctx, q, uid, featureID, t); err != nil {
545			return err
546		}
547	
548		return nil
549	}
