551	// upsertFeatureActivity normalizes feature-level activity events (scope_type=feature, task_id=NULL).
552	// Uses the partial unique index on (workspace_id, feature_id, sequence) WHERE task_id IS NULL.
553	func upsertFeatureActivity(ctx context.Context, q *database.Queries, uid pgtype.UUID, f domain.FeatureSnapshot) error {
554		for i, evt := range f.Activity {
555			raw, _ := json.Marshal(evt) //nolint:errcheck
556			_, err := q.UpsertFeatureActivityEvent(ctx, database.UpsertFeatureActivityEventParams{
557				WorkspaceID: uid,
558				ScopeType:   "feature",
559				FeatureID:   f.FeatureID,
560				Action:      ptrStr(evt.Action),
561				Actor:       ptrStr(evt.Actor),
562				OccurredAt:  ptrStr(evt.OccurredAt.Format(time.RFC3339)),
563				Note:        ptrStr(evt.Note),
564				Sequence:    int32(i),
565				RawEvent:    raw,
566			})
567			if err != nil {
568				return fmt.Errorf("upsert feature activity %s[%d]: %w", f.FeatureID, i, err)
569			}
570		}
571		return nil
572	}
