574	// upsertTaskActivity normalizes task log entries (scope_type=task).
575	// Uses the partial unique index on (workspace_id, feature_id, task_id, sequence) WHERE task_id IS NOT NULL.
576	func upsertTaskActivity(ctx context.Context, q *database.Queries, uid pgtype.UUID, featureID string, t domain.TaskSnapshot) error {
577		for i, evt := range t.Activity {
578			raw, _ := json.Marshal(evt) //nolint:errcheck
579			_, err := q.UpsertTaskActivityEvent(ctx, database.UpsertTaskActivityEventParams{
580				WorkspaceID: uid,
581				ScopeType:   "task",
582				FeatureID:   featureID,
583				TaskID:      t.TaskID,
584				Action:      ptrStr(evt.Action),
585				Actor:       ptrStr(evt.Actor),
586				OccurredAt:  ptrStr(evt.OccurredAt.Format(time.RFC3339)),
587				Note:        ptrStr(evt.Note),
588				Sequence:    int32(i),
589				RawEvent:    raw,
590			})
591			if err != nil {
592				return fmt.Errorf("upsert task activity %s/%s[%d]: %w", featureID, t.TaskID, i, err)
593			}
594		}
595		return nil
596	}
