598	// buildFeatureSnapshot reconstructs a FeatureSnapshot from the database rows.
599	func buildFeatureSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, f database.WorkspaceFeature) (domain.FeatureSnapshot, error) {
600		docs, err := q.ListFeatureDocuments(ctx, database.ListFeatureDocumentsParams{
601			WorkspaceID: uid,
602			FeatureID:   f.FeatureID,
603		})
604		if err != nil {
605			return domain.FeatureSnapshot{}, dbErr("list docs for snapshot", err)
606		}
607	
608		tasks, err := q.ListFeatureTasks(ctx, database.ListFeatureTasksParams{
609			WorkspaceID: uid,
610			FeatureID:   f.FeatureID,
611		})
612		if err != nil {
613			return domain.FeatureSnapshot{}, dbErr("list tasks for snapshot", err)
614		}
615	
616		docSnaps := make([]domain.DocumentSnapshot, 0, len(docs))
617		for _, d := range docs {
618			ds := domain.DocumentSnapshot{
619				DocumentType: d.DocumentType,
620				SourcePath:   d.SourcePath,
621			}
622			if d.URL != nil {
623				ds.URL = *d.URL
624			}
625			docSnaps = append(docSnaps, ds)
626		}
627	
628		taskSnaps := make([]domain.TaskSnapshot, 0, len(tasks))
629		for _, t := range tasks {
630			taskSnaps = append(taskSnaps, rowToTaskSnapshot(t))
631		}
632	
633		fs := domain.FeatureSnapshot{
634			FeatureID:  f.FeatureID,
635			Title:      f.Title,
636			SourcePath: f.SourcePath,
637			Documents:  docSnaps,
638			Tasks:      taskSnaps,
639		}
640		if f.FeatureStatus != nil {
641			fs.Status = *f.FeatureStatus
642		}
643		if f.CurrentStage != nil {
644			fs.CurrentStage = *f.CurrentStage
645		}
646		if f.NextAction != nil {
647			fs.NextAction = *f.NextAction
648		}
649		if f.SourceHash != nil {
650			fs.SourceHash = *f.SourceHash
651		}
652		return fs, nil
653	}
654	
655	// rowToTaskSnapshot converts a database row to a domain.TaskSnapshot.
656	func rowToTaskSnapshot(t database.WorkspaceTask) domain.TaskSnapshot {
657		ts := domain.TaskSnapshot{
658			TaskID:     t.TaskID,
659			FeatureID:  t.FeatureID,
660			Title:      t.Title,
661			SourcePath: t.SourcePath,
662		}
663		if t.Repo != nil {
664			ts.Repo = *t.Repo
665		}
666		if t.Status != nil {
667			ts.Status = *t.Status
668		}
669		if t.BlockedReason != nil {
670			ts.BlockedReason = *t.BlockedReason
671		}
672		if t.Branch != nil {
673			ts.Branch = *t.Branch
674		}
675		if t.SourceHash != nil {
676			ts.SourceHash = *t.SourceHash
677		}
678		ts.DependsOn = unmarshalStringSlice(t.DependsOn)
679		if len(t.Execution) > 0 {
680			var m map[string]interface{}
681			_ = json.Unmarshal(t.Execution, &m)
682			ts.Execution = m
683		}
684		if len(t.Pr) > 0 {
685			var m map[string]interface{}
686			_ = json.Unmarshal(t.Pr, &m)
687			ts.PR = m
688		}
689		if len(t.WorkspacePr) > 0 {
690			var m map[string]interface{}
691			_ = json.Unmarshal(t.WorkspacePr, &m)
692			ts.WorkspacePR = m
693		}
694		return ts
695	}
696	
697	// rowToFeatureSummary converts feature row + task list to a domain.FeatureSummary.
698	func rowToFeatureSummary(f database.WorkspaceFeature, tasks []database.WorkspaceTask) domain.FeatureSummary {
699		counts := domain.TaskCounts{}
700		for _, t := range tasks {
701			if t.FeatureID != f.FeatureID {
702				continue
703			}
704			counts.Total++
705			if t.Status == nil {
706				continue
707			}
708			switch *t.Status {
709			case "done":
710				counts.Done++
711			case "in_progress":
712				counts.InProgress++
713			case "blocked":
714				counts.Blocked++
715			case "ready":
716				counts.Ready++
717			case "todo":
718				counts.Todo++
719			}
720		}
721	
722		fs := domain.FeatureSummary{
723			FeatureID:  f.FeatureID,
724			Title:      f.Title,
725			UpdatedAt:  f.UpdatedAt.Time,
726			TaskCounts: counts,
727		}
728		if f.FeatureStatus != nil {
729			fs.Status = *f.FeatureStatus
730		}
731		if f.CurrentStage != nil {
732			fs.CurrentStage = *f.CurrentStage
733		}
734		return fs
735	}
736	
737	// rowToTaskSummary converts a workspace_tasks row to domain.TaskSummary.
738	func rowToTaskSummary(t database.WorkspaceTask) domain.TaskSummary {
739		ts := domain.TaskSummary{
740			TaskID:    t.TaskID,
741			FeatureID: t.FeatureID,
742			Title:     t.Title,
743		}
744		if t.Status != nil {
745			ts.Status = *t.Status
746		}
747		if t.Repo != nil {
748			ts.Repo = *t.Repo
749		}
750		if t.Branch != nil {
751			ts.Branch = *t.Branch
752		}
753		if t.BlockedReason != nil {
754			ts.BlockedReason = *t.BlockedReason
755			ts.IsBlocked = true
756		}
757		return ts
758	}
759	
760	// rowToActivityEvent converts a database row to domain.ActivityEvent.
761	func rowToActivityEvent(r database.WorkspaceActivityEvent) domain.ActivityEvent {
762		evt := domain.ActivityEvent{
763			Scope: r.ScopeType,
764		}
765		if r.Action != nil {
766			evt.Action = *r.Action
767		}
768		if r.Actor != nil {
769			evt.Actor = *r.Actor
770		}
771		if r.Note != nil {
772			evt.Note = *r.Note
773		}
774		if r.FeatureID != nil {
775			evt.FeatureID = *r.FeatureID
776		}
777		if r.TaskID != nil {
778			evt.TaskID = *r.TaskID
779		}
780		if r.OccurredAt != nil {
781			if t, err := time.Parse(time.RFC3339, *r.OccurredAt); err == nil {
782				evt.OccurredAt = t
783			}
784		}
785		return evt
786	}
787	
788	// syncRunRowToDomain converts a database sync run row to domain.SyncRun.
789	func syncRunRowToDomain(r database.WorkspaceSyncRun) *domain.SyncRun {
790		sr := &domain.SyncRun{
791			ID:          uuidStr(r.ID),
792			WorkspaceID: uuidStr(r.WorkspaceID),
793			Trigger:     r.Trigger,
794			Mode:        r.Mode,
795			Status:      domain.SyncStatus(r.Status),
796			StartedAt:   r.StartedAt.Time,
797		}
798		if r.CommitSha != nil {
799			sr.CommitSHA = *r.CommitSha
800		}
801		if r.ErrorCode != nil {
802			sr.ErrorCode = *r.ErrorCode
803		}
804		if r.ErrorMessage != nil {
805			sr.ErrorMsg = *r.ErrorMessage
806		}
807		if r.FinishedAt.Valid {
808			t := r.FinishedAt.Time
809			sr.FinishedAt = &t
810		}
811		return sr
812	}
813	
814	// syncRunToSourceState derives a SourceState from the latest sync run.
815	func syncRunToSourceState(r *database.WorkspaceSyncRun, threshold *time.Duration) domain.SourceState {
816		if r == nil || r.ID == (pgtype.UUID{}) {
817			return domain.StaleState(nil)
818		}
819		thr := domain.DefaultStaleThreshold
820		if threshold != nil {
821			thr = *threshold
822		}
823		return domain.DeriveSourceState(syncRunRowToDomain(*r), thr)
824	}
825	
826	// githubRepoURL fetches the repo URL from workspace_github_sources (best-effort).
827	func githubRepoURL(ctx context.Context, q *database.Queries, uid pgtype.UUID) string {
828		src, err := q.GetGitHubSource(ctx, uid)
829		if err != nil {
830			return ""
831		}
832		return src.RepoURL
833	}
834	
835	// parseUUID parses a plain UUID string into pgtype.UUID.
836	func parseUUID(s string) (pgtype.UUID, error) {
837		var uid pgtype.UUID
838		if err := uid.Scan(s); err != nil {
839			return pgtype.UUID{}, domain.NewValidationError(domain.ErrValidationMissingInput, "invalid workspace id: "+s)
840		}
841		return uid, nil
842	}
843	
844	// uuidStr renders a pgtype.UUID as a lowercase hyphenated string.
845	func uuidStr(u pgtype.UUID) string {
846		if !u.Valid {
847			return ""
848		}
849		b := u.Bytes
850		return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
851			b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
852	}
853	
854	// ptrStr returns nil if s is empty, otherwise returns &s.
855	func ptrStr(s string) *string {
856		if s == "" {
857			return nil
858		}
859		return &s
860	}
861	
862	// unmarshalStringSlice decodes a JSON array of strings.
863	func unmarshalStringSlice(raw json.RawMessage) []string {
864		if len(raw) == 0 {
865			return nil
866		}
867		var out []string
868		_ = json.Unmarshal(raw, &out)
869		return out
870	}
871	
872	// unmarshalExecution decodes execution JSON into domain.ExecutionContext.
873	func unmarshalExecution(raw json.RawMessage) domain.ExecutionContext {
874		if len(raw) == 0 {
875			return domain.ExecutionContext{}
876		}
877		var ec domain.ExecutionContext
878		_ = json.Unmarshal(raw, &ec)
879		return ec
880	}
881	
882	// dbErr wraps a database error in a domain SourceError.
883	func dbErr(op string, err error) error {
884		if strings.Contains(err.Error(), "no rows") {
885			return domain.NewDatabaseError(domain.ErrDatabaseNotFound, op+": not found")
886		}
887		return domain.NewDatabaseError(domain.ErrDatabaseQuery, op+": "+err.Error())
888	}
